package com.emssystem.emsleaveservice.pto.controller; import com.emssystem.emsleaveservice.pto.dto.request.*; import com.emssystem.emsleaveservice.pto.dto.response.PtoRequestResponse; import com.emssystem.emsleaveservice.pto.enums.PtoRequestStatus; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RequestMapping("/api/pto/requests") public interface PtoRequestController{@PostMapping PtoRequestResponse create(@RequestHeader("X-User-Id") UUID userId,@Valid @RequestBody CreatePtoRequest request);@GetMapping("/{id}") PtoRequestResponse get(@PathVariable Long id);@GetMapping("/me") List<PtoRequestResponse> mine(@RequestHeader("X-User-Id") UUID userId);@GetMapping List<PtoRequestResponse> list(@RequestParam(required=false) PtoRequestStatus status,@RequestParam(required=false) Long employeeId);@PostMapping("/{id}/decision") PtoRequestResponse review(@RequestHeader("X-User-Id") UUID reviewer,@PathVariable Long id,@Valid @RequestBody ReviewPtoRequest request);@PostMapping("/{id}/cancel") PtoRequestResponse cancel(@RequestHeader("X-User-Id") UUID userId,@PathVariable Long id,@Valid @RequestBody CancelPtoRequest request);}
